insert into questions (topic, subtopic, question_text, choices, correct_answer, explanation, wrong_answer_explanations, exam_trap, memory_takeaway, difficulty, source_type)
values
('General Principles','Cash Flow','A client earns $120,000 and spends $90,000 annually. What is savings rate?','{"A":"15%","B":"20%","C":"25%","D":"30%"}'::jsonb,'C','Savings rate is 30,000/120,000 = 25%.','{"A":"Incorrect calculation.","B":"Incorrect calculation.","C":"Correct.","D":"Overstates savings."}'::jsonb,'Choosing a familiar but less precise concept.','Use savings divided by gross income.','medium','original'),
('General Principles','Net Worth','Assets are $800,000 and liabilities are $260,000. Net worth is:','{"A":"$440,000","B":"$520,000","C":"$540,000","D":"$1,060,000"}'::jsonb,'C','Net worth equals assets minus liabilities.','{"A":"Understates.","B":"Arithmetic error.","C":"Correct.","D":"Adds instead of subtracts."}'::jsonb,'Sign error.','Assets minus liabilities.','medium','original'),
('Insurance','Life Insurance','A term policy is best described as:','{"A":"Permanent cash-value coverage","B":"Coverage for a specified period","C":"Investment-only product","D":"Annuity contract"}'::jsonb,'B','Term insurance covers a specific period.','{"A":"Describes whole life.","B":"Correct.","C":"Not insurance.","D":"Different product."}'::jsonb,'Confusing insurance types.','Term = temporary coverage.','easy','original'),
('Insurance','Disability','Which definition is generally most favorable to insured?','{"A":"Any occupation","B":"Own occupation","C":"Modified occupation","D":"Transitional occupation"}'::jsonb,'B','Own occupation is often more favorable.','{"A":"More restrictive.","B":"Correct.","C":"Not broadest.","D":"Not standard best choice."}'::jsonb,'Missing wording nuance.','Own-occupation is client-friendly.','medium','original'),
('Investments','Risk','Which metric measures portfolio volatility?','{"A":"Beta","B":"Sharpe ratio","C":"Standard deviation","D":"Yield to maturity"}'::jsonb,'C','Standard deviation measures dispersion of returns.','{"A":"Relative market sensitivity.","B":"Risk-adjusted return.","C":"Correct.","D":"Bond metric."}'::jsonb,'Picking familiar but wrong metric.','Volatility = standard deviation.','easy','original'),
('Investments','Asset Allocation','A 30-year horizon generally supports:','{"A":"Higher equity allocation","B":"Higher cash allocation","C":"All bonds","D":"No diversification needed"}'::jsonb,'A','Long horizon supports higher growth allocation.','{"A":"Correct.","B":"Too conservative.","C":"Not diversified.","D":"Incorrect principle."}'::jsonb,'Ignoring horizon.','Time horizon drives risk capacity.','easy','original'),
('Tax Planning','Capital Gains','Long-term capital gains apply when asset is held:','{"A":"More than 6 months","B":"More than 1 year","C":"At least 30 days","D":"Any period"}'::jsonb,'B','Long-term starts after more than one year.','{"A":"Too short.","B":"Correct.","C":"Too short.","D":"False."}'::jsonb,'Forgetting cutoff.','>1 year = long-term.','easy','original'),
('Tax Planning','Deductions','Above-the-line deductions primarily reduce:','{"A":"Tax credits","B":"Adjusted gross income","C":"Payroll tax","D":"State withholding"}'::jsonb,'B','They lower AGI.','{"A":"Different mechanism.","B":"Correct.","C":"Not directly.","D":"Not directly."}'::jsonb,'Confusing tax terms.','Above-the-line reduces AGI.','medium','original'),
('Retirement Planning','401(k)','Catch-up contributions are generally available starting at age:','{"A":"45","B":"50","C":"55","D":"59½"}'::jsonb,'B','Catch-up typically begins at 50.','{"A":"Too early.","B":"Correct.","C":"Too late.","D":"Incorrect threshold."}'::jsonb,'Age threshold trap.','Age 50 triggers catch-up.','easy','original'),
('Retirement Planning','Distribution','Sequence risk is most relevant during:','{"A":"Accumulation","B":"Distribution","C":"Education funding","D":"Mortgage underwriting"}'::jsonb,'B','Early bad returns during withdrawal phase hurt sustainability.','{"A":"Less impact early.","B":"Correct.","C":"Different goal.","D":"Unrelated."}'::jsonb,'Phase confusion.','Sequence risk matters in retirement income.','medium','original'),
('Estate Planning','Probate','A revocable living trust can help:','{"A":"Eliminate all taxes","B":"Avoid probate for titled assets","C":"Increase Social Security","D":"Avoid creditors always"}'::jsonb,'B','Trust-titled assets often avoid probate.','{"A":"Doesn''t eliminate all taxes.","B":"Correct.","C":"Unrelated.","D":"Not guaranteed."}'::jsonb,'Overstating trust benefits.','Trust helps probate efficiency.','medium','original'),
('Estate Planning','Beneficiaries','Which generally overrides a will?','{"A":"Letter of instruction","B":"Beneficiary designation","C":"Household inventory","D":"Executor memo"}'::jsonb,'B','Beneficiary forms govern many account transfers.','{"A":"Not controlling document.","B":"Correct.","C":"Informational only.","D":"Not legally controlling."}'::jsonb,'Document hierarchy trap.','Beneficiary forms often control.','medium','original'),
('Education Planning','529 Plans','Qualified withdrawals from a 529 are generally:','{"A":"Taxable federally","B":"Tax-free federally","C":"Always penalized","D":"Only for graduate school"}'::jsonb,'B','Qualified distributions are tax-free federally.','{"A":"False for qualified use.","B":"Correct.","C":"False.","D":"Too narrow."}'::jsonb,'Overgeneralizing penalties.','Qualified 529 use is tax-advantaged.','easy','original'),
('Education Planning','Financial Aid','Student-owned custodial assets are usually:','{"A":"Ignored","B":"Assessed more heavily","C":"Always tax-free","D":"Automatically annuitized"}'::jsonb,'B','Student assets are often assessed at a higher rate than parent assets.','{"A":"Not ignored.","B":"Correct.","C":"Tax status isn''t aid formula.","D":"False."}'::jsonb,'Aid-formula misunderstanding.','Ownership affects aid impact.','medium','original'),
('Ethics','Fiduciary','Under fiduciary duty, CFP professionals must:','{"A":"Maximize commissions","B":"Act in client best interest","C":"Guarantee returns","D":"Avoid written plans"}'::jsonb,'B','Fiduciary standard centers client interests.','{"A":"Conflict of interest.","B":"Correct.","C":"Impossible standard.","D":"Not required."}'::jsonb,'Ethics wording trap.','Fiduciary = client first.','easy','original'),
('Ethics','Conflicts','Best practice for conflicts of interest is to:','{"A":"Conceal immaterial conflicts","B":"Disclose and manage conflicts","C":"Ignore with sophisticated clients","D":"Delegate disclosure"}'::jsonb,'B','Conflicts should be disclosed and managed.','{"A":"Unethical.","B":"Correct.","C":"Still required.","D":"Professional remains responsible."}'::jsonb,'Disclosure trap.','Disclose + manage conflicts.','easy','original'),
('Investments','Bonds','When interest rates rise, existing bond prices usually:','{"A":"Rise","B":"Fall","C":"Stay flat","D":"Double"}'::jsonb,'B','Bond prices and rates move inversely.','{"A":"Opposite relation.","B":"Correct.","C":"Not typical.","D":"Implausible."}'::jsonb,'Inverse relationship trap.','Rates up, bond prices down.','easy','original'),
('Tax Planning','Roth IRA','Qualified Roth IRA distributions are generally:','{"A":"Taxable and penalized","B":"Tax-free if requirements met","C":"Always ordinary income","D":"Only first-home use"}'::jsonb,'B','Qualified Roth distributions are tax-free.','{"A":"False.","B":"Correct.","C":"False.","D":"Too narrow."}'::jsonb,'Qualification-rule trap.','Roth qualified = tax-free.','easy','original'),
('Insurance','Property & Casualty','A higher deductible usually causes premiums to:','{"A":"Increase","B":"Decrease","C":"Stay unchanged","D":"Become deductible"}'::jsonb,'B','Higher deductible lowers premium by shifting risk to insured.','{"A":"Opposite effect.","B":"Correct.","C":"Usually changes.","D":"Unrelated."}'::jsonb,'Risk-sharing trap.','Higher deductible, lower premium.','easy','original'),
('General Principles','Goal Prioritization','Best first step in prioritizing goals is:','{"A":"Pick highest-return asset","B":"Clarify time horizon and importance","C":"Buy insurance immediately","D":"Rebalance quarterly"}'::jsonb,'B','Planning begins with clear goals and timing.','{"A":"Premature action.","B":"Correct.","C":"May be later step.","D":"Portfolio maintenance, not first step."}'::jsonb,'Jumping to implementation.','Define goals before tactics.','easy','original');
